  ["_GameCornerMiddleAgedMan2WantSomeCoinsText"] = "……怎么了？\n想要一些代币吗？",
  ["_GameCornerMiddleAgedMan2YouHaveLotsOfCoinsText"] = "代币盒已满了呀。",
  ["_GastlyDexEntry"] = "它似乎会在没人居住的\n旧屋子里出现。形状不清，\n仿佛就像是气体一样。",
  ["_GengarDexEntry"] = "如果你突然感到寒气逼近，\n就说明耿鬼在你身边，或许\n它已经在你身上下了诅咒。",
  ["_GeodudeDexEntry"] = "大多栖息于山路。由于\n不留神踩到它会使它\n大发雷霆，得多加小心。",
  ["_GloomDexEntry"] = "奇臭无比！即使如此，\n一千个人里总会出现\n一个人喜欢闻这种味道。",
  ["_GolbatDexEntry"] = "难以察觉它会从哪里悄悄\n接近。它会用尖锐的牙咬住\n对手，同时使劲地吸血。",
  ["_GoldeenDexEntry"] = "到了产卵期你就可以看到\n成群的角金鱼逆流而行\n或是攀登瀑布。",
  ["_GolduckDexEntry"] = "它靠修长的四肢\n和发达的大脚蹼\n在湖里优雅地游泳。",
  ["_GolemDexEntry"] = "刚蜕皮时浑身都白白的\n非常柔软，但是接触到\n空气之后会迅速变坚硬。",
  ["_GravelerDexEntry"] = "常在山路上滚来滚去。\n滚动时从来不关心\n前面的路上都有什么。",
  ["_GrimerDexEntry"] = "它由囤积的淤泥而形成。\n臭到让人无法碰触，凡是\n它走过的地方都寸草不生。",
  ["_GrowlitheDexEntry"] = "性格很容易和人亲近，\n但是会对进入自己领地的\n敌人狂吠。",
  ["_GyaradosDexEntry"] = "性格蛮横爱破坏。在古代，\n这个恐怖的宝可梦曾有过把\n整座城市烧成焦土的记录。",
  ["_HallOfFameOakText"] = "大木：……嗯哼！\n{PLAYER}！祝贺你！\012历代宝可梦联盟中，\n每一只在训练家身边\011大展身手的宝可梦……\012都会被记录在这个楼层，\n作为永恒的表彰！\012宝可梦训练家们\n将这样的表彰\011称为“登入名人堂”！\011这是至高无上的喜悦！\012{PLAYER}！\n你在经历了激烈的对决后，\011成为了联盟冠军！\012接下来就把{PLAYER}和\n宝可梦们的名字\011也记录于此吧！",
  ["_HaunterDexEntry"] = "被它舔到时生命力会被\n吸走，身体会不受控制地\n不停颤抖，最后一命呜呼。",
  ["_HitmonchanDexEntry"] = "它的拳击好似钻头一般！\n在它的攻击之下，哪怕是\n水泥墙也会被钻出洞来。",
  ["_HitmonleeDexEntry"] = "在踢中敌人的瞬间，\n脚底会变得像钻石般坚硬，\n将对手踢成碎片。",
  ["_HorseaDexEntry"] = "在感到危险时\n会从嘴里用力地\n喷出水或者特殊的墨汁。",
  ["_HypnoDexEntry"] = "无意中遇到它的时候，若意\n外和他对上视线会很危险。\n它手上的钟摆会让人睡着。",
  ["_IvysaurDexEntry"] = "它的花苞会在吸收养分后\n长大。当花苞发出香味时，\n就预示着它快要开花了。",
  ["_JigglypuffDexEntry"] = "它会用圆溜溜的大眼睛盯着\n对手唱起不可思议的歌曲，\n舒服的歌曲会让对手睡着。",
  ["_JolteonDexEntry"] = "稍微受点刺激\n就会大叫或生气，\n每当心情变化时都会蓄电。",
  ["_JynxDexEntry"] = "以独特的节奏悠然移动，\n仿佛是在跳舞。走路的姿势\n如同在扭腰一样。",
  ["_KabutoDexEntry"] = "由化石复活而成的宝可梦。\n在藏匿于海底时似乎会用背\n上的眼睛观察周围的情况。",
  ["_KabutopsDexEntry"] = "用纤细的身体快速游动。\n似乎会用镰刀撕裂猎物\n吸取体液。",
  ["_KadabraDexEntry"] = "当勇基拉在附近时，\n似乎会发生像是时钟倒转\n这样的怪事。",
  ["_KakunaDexEntry"] = "虽然几乎动也动不了，\n但是如果遇到了危险，有时\n似乎会竖起毒刺来反抗。",
  ["_KangaskhanDexEntry"] = "在腹部的袋子里养育自己的\n宝宝。为了保护宝宝，遇到\n什么样的敌人都不会退缩。",
  ["_KinglerDexEntry"] = "一边的钳子很是巨大，虽说\n硬如钢铁还拥有１万马力，\n但还是太重了。",
  ["_KoffingDexEntry"] = "在炎热的地方，它体内的\n气体会由于膨胀而产生\n爆炸的危险，需要注意。",
  ["_KrabbyDexEntry"] = "钳子是它强悍的武器，但在\n攻击时钳子偶尔会脱落。\n脱落后很快会长出新的来。",
  ["_LancesRoomLanceBeforeBattleText"] = "是嘛！原来你就是\n{PLAYER}啊！\012我是四天王的统帅！\n龙使者阿渡……！\012你应该也知道，\n龙是神圣的传说中的生物！\012虽然不容易捕捉，\n但是只要努力培养，\011力量将会天下无双！\012它们的身体结实得很，\n耍小聪明的攻击\011动不了它们一根汗毛！\012……那好吧！\n差不多可以开始了！\012还是说你现在准备\n卷铺盖回家呢？\011{PLAYER}！",
  ["_LaprasDexEntry"] = "它拥有可以理解人类语言的\n温柔之心。会把人载在背上\n渡过大海。",
  ["_LickitungDexEntry"] = "它２米长的舌头比前肢更能\n灵活地移动。不知为何，\n被它舔到之后会觉得发麻。",
  ["_LooksContentText"] = "好像睡得很舒服的样子。",
  ["_MachampDexEntry"] = "仅靠１只手臂的力量便可\n推动一座山。４只手一起\n可以打出极为强力的拳击。",
  ["_MachokeDexEntry"] = "只要解开系在腰上的限制它\n力量的腰带，豪力就会变得\n势不可挡。",
  ["_MachopDexEntry"] = "它体格虽小却力大无比。\n不但如此，它还精通各种\n格斗技能，实力十分惊人。",
  ["_MagikarpDexEntry"] = "因靠不住而出名的宝可梦。\n它们会在海、河、池子、\n水洼等各种地方游来游去。",
  ["_MagmarDexEntry"] = "出生在火山口。因为它的\n全身都在燃烧，所以人们\n难以分辨它和火球的区别。",
  ["_MagnemiteDexEntry"] = "天生就拥有遮断重力的\n能力，可以一边发出\n电磁波一边在空中移动。",
  ["_MagnetonDexEntry"] = "一直在发射神秘的电波，\n半径１公里内的气温\n会升高２度。",
  ["_MankeyDexEntry"] = "身体轻盈，在树上生活。\n常因鸡毛蒜皮的小事发火\n而飞扑到周围的东西上。",
  ["_MarowakDexEntry"] = "身体曾经又小又弱，\n在习惯了使用骨头战斗后\n才变成了粗暴的性格。",
  ["_MeowthDexEntry"] = "貌似一到晚上就精力充沛。\n喜欢又圆又亮的东西，\n发现了就一定要捡走。",
  ["_MetapodDexEntry"] = "它会让外壳变硬来保护\n自己。但遇到强烈冲击时，\n它的身体还是会被撞出来。",
  ["_MewDexEntry"] = "用显微镜可以看到\n它身上极短极细\n且密集的体毛。",
  ["_MewtwoDexEntry"] = "超梦的基因几乎和梦幻\n完全一样，但是大小和性格\n却迥异得让人吃惊。",
  ["_MoltresDexEntry"] = "传说的鸟宝可梦。当它挥舞\n起剧烈燃烧着的双翅，\n哪怕是夜空也会被点亮。",
  ["_MrMimeDexEntry"] = "擅长演哑剧，一直在练习。\n即使空无一物，也能让人\n觉得那里真的有东西存在。",
  ["_MtMoon1FBewareZubatSign"] = "小心！\n超音蝠会吸血！",
  ["_MtMoonJessieJamesText1"] = "且慢！",
  ["_MtMoonJessieJamesText2"] = "化石是我们火箭队的！",
  ["_MtMoonJessieJamesText3"] = "我竟然会输给\n这样的孩子……",
  ["_MtMoonJessieJamesText4"] = "好讨厌的感觉啊～！",
  ["_MukDexEntry"] = "非常难闻！气味臭到让人\n窒息，但由于鼻子的退化，\n它自己完全闻不到味道。",
  ["_Museum1FScientist2TakeThisToAPokemonLabText"] = "嘘……！\n偷偷告诉你，\011我推测这个琥珀里面\011留有宝可梦的遗传基因！\012如果能让它复活，\n那简直就是\011宝可梦的一大发现！\012可惜这里的同事们\n没人把我说的话当回事。\012所以啊……\n我需要你的帮助！\012麻烦你拿着这个琥珀，\n找一家研究所，\011请人帮我调查个究竟吧！",
  ["_Museum2FPikachuText1"] = "你的皮卡丘看上去\n和你关系不是特别好。\011如果可以的话，能不能\011把它让给我的女儿呢？",
  ["_Museum2FPikachuText2"] = "好想要你的皮卡丘，\n但看它和你关系这么好，\011我也确实不好意思\011问你要啊……",
  ["_NameRatersHouseNameRaterComeAnyTimeYouLikeText"] = "这样啊。\n知道了，你有空再来吧。",
  ["_NidokingDexEntry"] = "通过活用自己钢一般坚硬的\n皮肤来使出强力的撞击。\n犄角坚硬得能够刺穿钻石。",
  ["_NidoqueenDexEntry"] = "坚硬的鳞片覆盖着强壮的\n身体。据说它的鳞片\n会自己长出新的。",
  ["_NidoranFDexEntry"] = "它性格温顺不喜欢战斗，\n但由于小犄角中含有毒液，\n请一定要小心提防。",
  ["_NidoranMDexEntry"] = "一直竖起它的大耳朵感知\n周围的情形。当它察觉到\n危险便会使用毒针。",
  ["_NidorinaDexEntry"] = "待在巢穴深处的时候，\n它必会把身上的刺收起来。\n这表明它正处于放松状态。",
  ["_NidorinoDexEntry"] = "头上的犄角里含有毒素，\n当犄角撞穿了什么东西时，\n毒素就会随着冲击而流出。",
  ["_NinetalesDexEntry"] = "传说这种宝可梦\n是由９位圣者\n合体之后而诞生的。",
  ["_NoPokemonText"] = "里面没有宝可梦！",
  ["_NotEnoughMemoryText"] = "黄版的\n内存空间不足。",
  ["_NurseChanseyText"] = "吉利蛋：吉～利～！",
  ["_OaksLabGivePokeballsExplanationText"] = "\012当野生的宝可梦\n扑过来时就是机会！\012就像我刚才展示的那样，\n把精灵球“咻”地扔出去，\011就能捉到宝可梦了！\012但是……也要明白并不是\n每一次都会顺利捉到！\012健康的宝可梦很容易逃脱，\n所以运气也是需要的！",
  ["_OaksLabOak1GoAheadItsYours"] = "大木：那么，\n快点去拿吧！",
  ["_OaksLabOak1ParcelThanksText"] = "\012哦哦！这不是\n我预订的特殊精灵球嘛。\011真是谢谢你了，\011{PLAYER}！\012顺便，刚才忘了说了，\n我有事要拜托……",
  ["_OaksLabOak1YouShouldTalkToIt"] = "大木：偶尔和它说说话，\n看看它的情况，\011应该会很不错吧！",
  ["_OaksLabOak1YourPokemonCanFightText"] = "大木：对了！\n哪怕有野生的宝可梦出现，\011只要与它们战斗，\011就能前往下一个城镇了！",
  ["_OaksLabOakBePatientText"] = "大木：嗨！着什么急呀\n{RIVAL}！\011我过一会儿也会给你的！",
  ["_OaksLabOakChooseMonText"] = "大木：哦哦，{RIVAL}？\n什么呀，你早就来了吗？\012明明之前跟你说了，\n让你过一会儿再来的……\012嘛，算了。\n你在那里稍微等我一下。\012快看，{PLAYER}！\n那边有个圆圆的小球对吧？\012嚯嚯！\012它叫做精灵球，\n里面装着宝可梦呢。\012我准备把它给你！\n那么，快点去拿吧！",
  ["_OaksLabOakGivesText"] = "大木：{PLAYER}！\n这家伙是刚才那只宝可梦！\012虽然才刚刚被捉到，\n还不太能和人类亲近，\011作为替代，这只给你吧！",
  ["_OaksLabOakIHaveARequestText"] = "大木：哦，{RIVAL}，\n你来得正好！\012我有事要拜托你们两个。",
  ["_OaksLabPikachuDislikesPokeballsText1"] = "大木：哎呀？",
  ["_OaksLabPikachuDislikesPokeballsText2"] = "大木：嚯！\012真是稀奇，\n那家伙好像讨厌精灵球……\012带着它一起走如何？\012这么做的话，\n它也会很高兴的吧！\012和它交谈的话，\n就能观察它的状况了！",
  ["_OaksLabReceivedText"] = "{PLAYER}从大木那里\n得到了{RAM:wNameBuffer}！",
  ["_OaksLabRivalGrampsIsntAroundText"] = "{RIVAL}：哟！\n{PLAYER}！\011大木爷爷不在这里呢！\012他说要给我宝可梦，\n所以这才急忙过来的……",
  ["_OaksLabRivalIllGetABetterPokemonThanYou"] = "{RIVAL}：哼！\n我之后要拿到\011比你的更好的宝可梦！",
  ["_OaksLabRivalMyPokemonHasGrownStrongerText"] = "{RIVAL}：爷爷，\n我的宝可梦成长了呢！\011来看一看吧。",
  ["_OaksLabRivalMyPokemonLooksStrongerText"] = "{RIVAL}：看起来，\n我的宝可梦更强呢。",
  ["_OaksLabRivalTakesText1"] = "{RIVAL}：{PLAYER}！\n这家伙就归我了！",
  ["_OaksLabRivalTakesText2"] = "{RIVAL}\n夺走了宝可梦！",
  ["_OaksLabRivalTakesText3"] = "大木：喂！{RIVAL}！\n你在干什么！",
  ["_OaksLabRivalTakesText4"] = "{RIVAL}：爷爷！\n我就想要这个嘛！",
  ["_OaksLabRivalTakesText5"] = "大木：真拿你没办法呢……\n好吧！那只宝可梦\011就给你了！\012本来我就打算也会给你\n１只宝可梦的……\012{PLAYER}，\n你到这边来一下吧。",
  ["_OaksLabThatsAPokeball"] = "是精灵球。\n里面装有宝可梦！",
  ["_OddishDexEntry"] = "若以为它是普通的草而将它\n拔起，就会听到它的叫声。\n这让人感到莫名的恐怖。",
  ["_OfficerJennyText1"] = "我最近捕获了\n一只喜欢捣乱的杰尼龟！\012要是能碰到个\n有水平的训练家，\011我想把杰尼龟托付出去……",
  ["_OfficerJennyText2"] = "那枚橙色徽章！\012看来你……\n是个有水平的训练家啊！\012我最近捕获了\n一只喜欢捣乱的杰尼龟！\012我能把它托付给你吗？",
  ["_OfficerJennyText3"] = "那就交给你咯！\n你要好好照顾它噢！",
  ["_OfficerJennyText4"] = "这该怎么办……\n这可真让人头疼。",
  ["_OfficerJennyText5"] = "杰尼龟过得好吗？",
  ["_OmanyteDexEntry"] = "用化石复原出的宝可梦，\n靠巧妙地弯曲它的１０条腿\n在古代的大海里飘荡。",
  ["_OmastarDexEntry"] = "它拥有锋利的牙齿，\n但据说它由于外壳过大，\n不易移动而导致灭绝。",
  ["_OnixDexEntry"] = "以惊人之势钻地觅食。在它\n通过之后形成的洞穴会被\n地鼠们当作自己的住处。",
  ["_PalletTownOakComeWithMe"] = "大木：就像这样，\n不知道什么时候会有\011宝可梦从草丛里扑过来！\012你要是有宝可梦的话，\n就可以战斗了。\011对了！\012请你跟我来吧！",
  ["_PalletTownOakThatWasCloseText"] = "大木：这样很危险的！\012野生的宝可梦\n会从草丛中扑过来！",
  ["_PalletTownOakWhewText"] = "大木：呼……",
  ["_ParasDexEntry"] = "它会通过挖洞来从树根里\n吸取营养，但大部分营养\n都会被背上的蘑菇抢走。",
  ["_ParasectDexEntry"] = "因虫子的精华不断被吸走，\n在思考的似乎已经不是\n虫子，而是背上的蘑菇了。",
  ["_PartyMenuUseTMText"] = "要教哪只宝可梦？",
  ["_PersianDexEntry"] = "额头上的宝石闪闪发亮！\n走路的姿态也十分优美，\n就像女王一样华丽高贵。",
  ["_PewterGymBrockBoulderBadgeInfoText"] = "\012当你有了灰色徽章，\n你的宝可梦会变得更强！\012学会招式“闪光”的\n宝可梦即使在战斗外，\011也能使用它了！",
  ["_PewterGymBrockPostBattleAdviceText"] = "在这个广阔的世界里\n生活着各种各样的人！\012他们或是让宝可梦对战，\n或是训练它们成长……\012我为了成为宝可梦培育家\n正在努力修行！\012你也很强大呢。\n要成为宝可梦训练家的话，\011我推荐你去华蓝市的道馆\011试试身手吧！",
  ["_PewterGymGuyText"] = "好嘞！\n那么，赶紧的……！\012嗯，对你的皮卡丘来说，\n要想在这个道馆获胜\011可是相当困难的啊！\012电属性攻击对小刚使用的\n地面属性的宝可梦，\011是完全无效的！",
  ["_PewterMartYoungsterText"] = "我从一个阴森森的大叔那里\n买了一只奇怪的宝可梦！\012真的是超级弱！\n白花了我¥500啊……",
  ["_PewterPokecenterText3"] = "宝可梦中心真的太棒了！\012就算宝可梦陷入睡眠、\n中毒、灼伤、麻痹等状态，\011也能恢复回来呢。",
  ["_PidgeotDexEntry"] = "以２马赫的飞行速度\n来觅食。它巨大的爪子\n是非常令人惧怕的武器。",
  ["_PidgeottoDexEntry"] = "拥有超群的体力，\n而且飞翔范围广，经常飞到\n很远的地方寻找食物。",
  ["_PidgeyDexEntry"] = "性格沉着冷静，即使\n受到攻击也很少反击，只会\n朝对手扬起沙子保护自己。",
  ["_PikachuDexEntry"] = "会将尾巴竖起来来感觉周围\n是否安全。所以如果随便\n去拉它的尾巴，会被咬喔。",
  ["_PikachuUnhappyText"] = "但是，{RAM:wNameBuffer}\n可不乐意啊！",
  ["_PinsirDexEntry"] = "用犄角全力夹击！由于低温\n会使它无法动弹，所以它会\n选择在温暖的地方生活。",
  ["_PokemonFanClubChairmanIntroText"] = "宝可梦发烧友俱乐部的会长\n正是老夫！\012老夫疼爱的宝可梦\n已经超过了１００只！\012要老夫说起宝可梦的事，\n那可是三天三夜\011都说不完哇！\012于是乎……\012你一定是来这里倾听老夫\n炫耀那些赞赞的\011宝可梦的吧？",
  ["_PokemonFanClubChairmanStoryText"] = "果然是吧！\n那老夫就开始喽！\012那啥……那就先介绍\n老夫钟爱的烈焰马吧……\012……它呀……就是……\n……可爱的唷……\011了不得哇……唔……\011……而且它啊……\011棒棒的…………\011……你也这么觉得吗……\011为啥噢……太喜欢了……\011……哈～！\012抱一抱唷……\n……它睡觉的时候哇……\011……对吧！\011……艺术品啊……！\011优美到飞天……\011…………哎哟！\011已经到这个点了！\011老夫说得太多喽！\012你听老夫称赞宝可梦\n听得还挺有耐心的哇！\011…收下老夫的一点心意吧！",
  ["_PokemonFanClubClefairyFanBetterText"] = "别胡说！\n我们家的皮皮\011比你的可爱百倍！",
  ["_PokemonFanClubClefairyFanNormalText"] = "快看！我们家的皮皮，\n尾巴多可爱啊！",
  ["_PokemonFanClubClefairyFanText"] = "最近，会长喜欢上了\n拍摄宝可梦的照片，\011然后把它贴在墙上这件事。\012他也帮我打印了一张\n皮皮的照片呢。",
  ["_PokemonFanClubClefairyText"] = "皮皮：皮～皮",
  ["_PokemonFanClubReceptionistText"] = "我们会长\n对宝可梦非常讲究！",
  ["_PokemonFanClubSeelFanText"] = "我也要使用连接线，\n把小海狮的照片打印出来！",
  ["_PokemonText"] = "宝可梦！",
  ["_PokemonTowerJessieJamesText1"] = "等一下！！",
  ["_PokemonTowerJessieJamesText2"] = "这个老头真是吵死了，\n我们就这样好好教训了他。\012不打败我们的话，\n就别想把老头救出来了！",
  ["_PokemonTowerJessieJamesText3"] = "你给我记住！",
  ["_PokemonTowerJessieJamesText4"] = "好讨厌的感觉啊～！",
  ["_PoliwagDexEntry"] = "漩涡的旋转方向\n好像会因出生地区而不同。\n比起走路，它更擅长游泳。",
  ["_PoliwhirlDexEntry"] = "据说它会在要被对手攻击时\n用腹部的漩涡让对方睡着，\n趁机逃跑。",
  ["_PoliwrathDexEntry"] = "他会用全身的肌肉奋力\n游泳，连奥林匹克选手\n都甘拜下风。",
  ["_PonytaDexEntry"] = "在用力跳跃之后，\n会用蹄子和脚上的肌肉\n来缓解着地时的撞击。",
  ["_PorygonDexEntry"] = "人们期待它能成为唯一能够\n飞到宇宙的宝可梦，\n然而至今也努力未果。",
  ["_PrimeapeDexEntry"] = "只有在谁都不在身边的时候\n才不生气，但几乎\n没有人目击过这种情况。",
  ["_PsyduckDexEntry"] = "一直被头痛困扰。\n能使用念力，但不知道那\n是否是出于它自己的意识。",
  ["_RaichuDexEntry"] = "体内电力累积到一定程度时\n性格会变得带有攻击性。\n在暗处看着就像是在发亮。",
  ["_RapidashDexEntry"] = "总之就是喜欢跑步。如果\n发现有谁跑得比自己更快，\n就会用尽全力去追赶。",
  ["_RaticateDexEntry"] = "它的后脚上长着小蹼，\n以便它在水中游泳\n寻找食物。",
  ["_RattataDexEntry"] = "有两颗大门牙，见啥咬啥。\n只要看到１只小拉达出没，\n附近必还住着４０只以上。",
  ["_RedBedroomSNESText"] = "{PLAYER}正在玩\nSNES！\nSuper Famicom！\011……\011是时候出发了！",
  ["_RedsHouse1FMomWakeUpText"] = "妈妈：……是这样啊，\n男孩子都是志在四方的嘛，\011嗯……电视上是这么说的！\012说起来，\n隔壁的大木博士\011正在找你哦。",
  ["_RedsHouse1FMomYouShouldRestText"] = "妈妈：{PLAYER}……！\n如果让宝可梦硬撑的话，\011它们会不喜欢你呢。\012要不要休息一下呢……？",
  ["_RefusingText"] = "{RAM:wNameBuffer}\n不喜欢它！",
  ["_RhydonDexEntry"] = "可以只用后腿行走，智力也\n发达了许多。像盔甲一样的\n皮肤可以抵挡住岩浆。",
  ["_RhyhornDexEntry"] = "单细胞的脑子只能思考一件\n事情。一旦它开始猛撞，\n直到睡着前都不会停止。",
  ["_RocketHideoutB4FRocketAfterBattleText"] = "糟了！我特地藏起来的\n电梯钥匙要没了！",
  ["_RocketHideoutB4FRocketBattleText"] = "哈哈哈！\n坐不了电梯是吧？\011你猜钥匙在谁手上呢？",
  ["_RocketHideoutB4FRocketEndBattleText"] = "不可能！",
  ["_RocketHideoutJessieJamesText1"] = "站住站住～！！",
  ["_RocketHideoutJessieJamesText2"] = "你上次在月见山\n给我们添了不少乱啊！\012是该跟你算算之前的帐了！",
  ["_RocketHideoutJessieJamesText3"] = "你可真是一个\n令人讨厌的小鬼头。",
  ["_RocketHideoutJessieJamesText4"] = "好讨厌的感觉啊～！",
  ["_Route10SuperNerd2BattleText"] = "对了、对了！\n你要看看我的宝可梦吗？",
  ["_Route12Fisher4AfterBattleText"] = "哈哈哈……没事！\n区区战败还不足以\011让我生气。",
  ["_Route12Gate2FBrunetteGirlYouCanHaveThisText"] = "我曾经最疼爱的宝可梦\n现在正沉睡在\011宝可梦塔里……\012……对了！\n我的招式学习器\011还是送给大哥哥吧！\011我留着它也没有用了……",
  ["_Route14CooltrainerM1AfterBattleText"] = "你也有秘传学习器呢。\n学会那些招式的宝可梦\011是无法忘记它们的哦。",
  ["_Route16Biker2EndBattleText"] = "我晕！",
  ["_Route17Biker10BattleText"] = "……好懒啊……想睡了，\n真麻烦啊……！",
  ["_Route22RivalBeforeBattleText2"] = "{RIVAL}：怎么？\n{PLAYER}！在这种\011地方又碰到你还真突然！\012那么……你也是要\n去宝可梦联盟对吧？\012徽章也全部\n收集到了吗！\011啊，是吗……干得不错！\012那在去宝可梦联盟前\n先用{PLAYER}\011来做一下热身运动好了！\012来战斗吧！",
  ["_Route24DamianText1"] = "我啊……真是太不擅长\n培育宝可梦了。\012这只小火龙也是，\n一直都弱不禁风的，\011我看着都觉得它太可怜……\011想要把它放生……\012如果你能好好培养它的话，\n就把它给你了？",
  ["_Route24DamianText2"] = "那么就拜托你了！",
  ["_Route24DamianText3"] = "是吗……那么，\n要在哪里把它放生呢……",
  ["_Route24DamianText4"] = "那只小火龙你还在培育吗？",
  ["_Route25CooltrainerF1EndBattleText"] = "状态不好。",
  ["_Route3Youngster3EndBattleText"] = "如果把新宝可梦\n带来的话，我就能赢你了。",
  ["_Route6CooltrainerF1AfterBattleText"] = "我现在明白了。\n计算并非宝可梦的一切。",
  ["_Route6CooltrainerF1BattleText"] = "我正在进行爱的特训，\n不要来妨碍我！",
  ["_Route6CooltrainerF1EndBattleText"] = "怎么会这样……\n课本上没有写呢。",
  ["_Route6CooltrainerM1AfterBattleText"] = "这样的话，\n她会讨厌我的……",
  ["_Route6CooltrainerM1BattleText"] = "这就是爱的特训，\n别来烦我啊。",
  ["_Route6CooltrainerM1EndBattleText"] = "这，\n这怎么可能……",
  ["_Route8CooltrainerF3AfterBattleText"] = "金黄市的门卫不让我过去。\n虽然他很克忠职守……\011但心眼却很坏！",
  ["_Route9AJAfterBattleText"] = "我会和穿山鼠一起，\n再以１００连胜为目标的！",
  ["_Route9AJBattleText"] = "我的目标是\n成为最强的训练家！",
  ["_Route9AJEndBattleText"] = "我的穿山鼠\n竟然输了……",
  ["_RunAwayText"] = "快点逃走吧！",
  ["_SSAnne2FRoomsGentleman3Text"] = "我虽游遍大千世界，\n在发现那个整天只会\011睡觉的家伙时，\011还是大跌眼镜了呢！\012没记错的话，\n它应该是这个宝可梦。",
  ["_SSAnneCaptainsRoomCaptainIFeelMuchBetterText"] = "船长：噢……真是感谢你！\n现在我感觉好多了……\012什么……？\n你想要看我表演居合斩？\012要是我身体状态还行的话\n就能展示给你看了……\012对啊！虽然不能亲自展示，\n但我可以把这个给你啊！\012让你的宝可梦学会的话，\n不论什么时候，你都可以\011看它表演居合斩了！",
  ["_SSAnneCaptainsRoomCaptainNotSickAnymoreText"] = "船长：呼。\012这会儿我感觉好多了！\n差不多该起航了。",
  ["_SafariZoneGateSafariZoneWorker1ThatllBe500PleaseText"] = "那么……！\n收您¥{NUM:wPriceTemp, 3 | LEADING_ZEROES | LEFT_ALIGN}！\012在这里只能使用狩猎专用的\n精灵球进行捕捉！\011……这些是给您的！\012{PLAYER}从前台那里\n得到了３０个狩猎球！",
  ["_SafariZoneLowCostText1"] = "\012……真是没办法，\n有多少就付多少钱吧。",
  ["_SafariZoneLowCostText2"] = "但是，\n球是不可能都给你的。",
  ["_SafariZoneLowCostText3"] = "\012真是够固执的……\012今天算你走运！\n就这一次，让你进去吧！",
  ["_SafariZoneLowCostText5"] = "没有带钱的人\n不允许进入！",
  ["_SafariZoneLowCostText6"] = "没带钱的人不让进！",
  ["_SafariZoneLowCostText7"] = "我说过了吧，\n没带钱的人不让进！",
  ["_SafariZoneLowCostText8"] = "说了不行，\n那就是不行……",
  ["_SaffronGateGuardGeeImThirstyText"] = "我是一个认真尽职的警卫！\n哎呀……有点口渴啊！\012喂喂！\n那边现在禁止通行！",
  ["_SaffronGateGuardYouCanGoOnThroughText"] = "\012……\n咕噜咕噜……\011……\011咕噜咕噜……\011如果想去\011金黄市的话……\011…………\011你就过去吧……\011记得去把饮料也分给\011另一边入口的警卫哦。",
  ["_SaffronGymYoungster1AfterBattleText"] = "克制超能力的属性？\n有倒是有。\011那就是虫属性！",
  ["_SandshrewDexEntry"] = "身体很干燥。\n但据说在夜里降温时，\n它的表皮上会有露水凝结。",
  ["_SandslashDexEntry"] = "它很擅长用爪子抓伤敌人。\n偶尔在战斗中会折断爪子，\n但到次日就会长出新的来。",
  ["_SavingText"] = "正在写入\n宝可梦记录……",
  ["_ScytherDexEntry"] = "突然从草丛里窜出来，\n用锋利的镰刀斩砍的样子\n仿佛就像是忍者。",
  ["_SeadraDexEntry"] = "摸它的背鳍会导致麻痹。\n为避免在睡觉时被水冲走，\n它会用尾巴缠住珊瑚。",
  ["_SeakingDexEntry"] = "雄性的职责是\n用头上的角\n打穿河里的石头筑巢。",
  ["_SeelDexEntry"] = "喜欢天寒地冻的地方，\n就算零下１０度\n也能愉快地游泳。",
  ["_ShellderDexEntry"] = "它的硬壳可以承受任何\n攻击，但是一旦硬壳打开，\n柔软的内部就会完全暴露。",
  ["_SilphCo10FSilphWorkerFImScaredText"] = "呜呜呜……\n我好害怕啊！",
  ["_SilphCo11FGiovanniText"] = "呵，是{PLAYER}吗？\n我们又见面了！\012我正在和西尔佛的社长\n讨论重要的商业计划。\012像你这样的小孩子，\n就别在大人的世界\011瞎掺和了！\012如果你无论如何都想插手，\n那我也只能让你\011吃些苦头了！",
  ["_SilphCo2FRocket1AfterBattleText"] = "菱形设计的地板，\n是传送方块！\012这可是\n高科技大楼内的移动方式。",
  ["_SilphCo5FRockerBattleText"] = "真奇怪啊。\n小孩子应该进不来的啊。",
  ["_SilphCo7FRivalDefeatedText"] = "很好～！\n看来你已经准备好\011面对火箭队的挑战了！",
  ["_SilphCo7FRocket1BattleText"] = "哎呀！\n发现一只小老鼠！",
  ["_SilphCoJessieJamesText1"] = "站住站住～！！",
  ["_SilphCoJessieJamesText2"] = "现在我们老大\n正在谈重要的生意！\012你可休想捣乱！",
  ["_SilphCoJessieJamesText3"] = "果然还是\n和之前一样……",
  ["_SilphCoJessieJamesText4"] = "那么接下来，\n我们就一如既往地……\012好讨厌的感觉啊～！",
  ["_SleepingPikachuText1"] = "哎呀？不在……",
  ["_SleepingPikachuText2"] = "哎呀？不在……",
  ["_SlowbroDexEntry"] = "在海边悠闲地生活。如果\n尾巴上的大舌贝脱落了，\n它就会变回呆呆兽。",
  ["_SlowpokeDexEntry"] = "非常呆，动作也很缓慢。\n从不在意时间的流逝，\n过着悠闲的生活。",
  ["_SnorlaxDexEntry"] = "就算是有些发霉的食物\n也能毫不在意地吃完，\n并且完全不会吃坏肚子。",
  ["_SpearowDexEntry"] = "不擅长高空飞行。会以\n超高速在地盘里四处盘旋，\n以保护自己地盘不被侵犯。",
  ["_SquirtleDexEntry"] = "通过从水面喷水来捕食。\n在危急时刻会将四肢\n缩入龟壳里保护自己。",
  ["_StarmieDexEntry"] = "据说当被称为其核心的中心\n部分闪烁着七色光芒时，\n就代表着它正在传达信息。",
  ["_StaryuDexEntry"] = "据说只要它身体的中心部分\n还存活着，即使被切成小块\n也能再生。",
  ["_SummerBeachHousePikachuText"] = "皮卡丘：皮卡～",
  ["_SummerBeachHousePoster1Text1"] = "冲浪大叔的随手记\012速度提升时，音乐\n听起来也会变得更快，\011更加有节奏！",
  ["_SummerBeachHousePoster1Text2"] = "专注冲浪３０年！\n冲浪大叔",
  ["_SummerBeachHousePoster2Text1"] = "冲浪的心得 其一：\012翻转之后，\n配合海浪的水面降落，\011这个是变帅气的诀窍！",
  ["_SummerBeachHousePoster2Text2"] = "大海之家。\n热烈欢迎宝可梦！",
  ["_SummerBeachHousePoster3Text1"] = "冲浪的心得 其二：\012跳跃时连续翻转，\n真的很帅气呢！",
  ["_SummerBeachHousePoster3Text2"] = "大海即是浪漫！",
  ["_SummerBeachHousePrinterText1"] = "这是什么……？\n是某种机器吗？",
  ["_SummerBeachHousePrinterText2"] = "上面写着：\n夏日海滩用打印装置。",
  ["_SummerBeachHousePrinterText3"] = "上面显示了\n当前的最高分！\012要打印吗？",
  ["_SummerBeachHousePrinterText4"] = "上面写着：\n夏日海滩用打印装置。\012上面显示了\n当前的最高分！\012要打印吗？",
  ["_SummerBeachHousePrinterText5"] = "打印完成。",
  ["_SummerBeachHousePrinterText6"] = "未能顺利打印。",
  ["_SummerBeachHouseSurfinDudeText1"] = "唔唔……\012那家伙就是冲浪皮卡丘吧！\n原来除了我之外，\011还有带着它的人啊……\012好！\n让你能游玩特别的\011冲浪游戏吧！\012要玩一下吗？",
  ["_SummerBeachHouseSurfinDudeText2"] = "还想要来玩的话，\n请随时过来！",
  ["_SummerBeachHouseSurfinDudeText3"] = "要玩冲浪游戏吗？",
  ["_SummerBeachHouseSurfinDudeText4"] = "要不要来一份\n拉面或者炒面呀？",
  ["_TangelaDexEntry"] = "全身被蓝色的蔓藤覆盖，\n真面目不为人知。据说，它\n的蔓藤会持续不断地生长。",
  ["_TaurosDexEntry"] = "精力充沛且个性火暴。一旦\n开始奔跑，在撞到东西之前\n都不会停下脚步。",
  ["_TentacoolDexEntry"] = "有时能在沙滩上发现它\n干巴巴的身体，但是\n它只要沾到水就能复活。",
  ["_TentacruelDexEntry"] = "它能让８０条触手\n自由伸缩，靠缠住猎物后\n注入毒素来让其变弱。",
  ["_TextIDErrorText"] = "{NUM:hTextID, 1, 2} 出错。",
  ["_Thanks3Text"] = "非常感谢！",
  ["_VaporeonDexEntry"] = "它的细胞与水分子相似，\n在它溶入于水后，\n你就完全看不见它了。",
  ["_VenomothDexEntry"] = "若失手把翅膀上的鳞粉沾到\n身上，不但很难去除，更糟\n的是毒素也会从那里渗入。",
  ["_VenonatDexEntry"] = "在明亮处你便能发现它具有\n雷达功能的大眼其实是由\n许多个小眼睛聚集而成的。",
  ["_VenusaurDexEntry"] = "它背上开出的大花\n能够吸收太阳光\n并将其转换为能量。",
  ["_VermilionGymLTSurgePreBattleText"] = "立正！欢迎来到\n枯叶道馆！\012瞧瞧，居然来了个\n小不点挑战者！\012哈哈！就凭你\n那一点点本事，\011居然也敢挑战我，\011胆量倒是不小！\012宝可梦对战\n就是战争！\011我会让你见识厉害！\012我要把你电到\n举手投降！",
  ["_VermilionGymLTSurgeThunderBadgeInfoText"] = "持有橙色徽章，\n宝可梦的速度\011会提高！\012而且可以在战斗外\n使用招式“飞翔”！\012你很特别，\n这是我的一点心意！",
  ["_VictreebelDexEntry"] = "用花蜜香味引诱猎物。据说\n被它吞入嘴里的东西，只要\n１天会溶解到骨头都不剩。",
  ["_VileplumeDexEntry"] = "为了散布有毒的花粉\n而摇动其巨大的花瓣，\n同时发出震耳的响声。",
  ["_ViridianCityOldManHadMyCoffeeNowText"] = "唔……\n我应该是喝多了。\011头有点痛……\012……什么？\n你说我挡了你的路？\011……不好意思啊。\012你在收集宝可梦图鉴是吗！\n为了向你道歉，让我来\011给你展示如何捕捉宝可梦！",
  ["_ViridianCityOldManLosingMyTouchText"] = "嗯，失败了呢～\n我确实不行了呢～\012这会儿\n精灵球也用完了呀。\012要不去附近的友好商店\n再买一些呢？",
  ["_ViridianCityOldManNotGoodEnoughForYouText"] = "是吗……\n是因为我不够出色吗。",
  ["_ViridianCityOldManWantMeToShowYouAgainText"] = "什么！？\n你又想来让我来教你\011捕捉宝可梦的方法吗？",
  ["_ViridianCityOldManWatchCloselyText"] = "嚯嚯！\n那就让我亲自给你\011示范看看吧！",
  ["_ViridianCityYoungster1Text"] = "你腰上挂着精灵球！\n……难道是宝可梦！\012能随时随地\n带着宝可梦到处走，\011真的好方便啊！",
  ["_ViridianForestCooltrainerFAfterBattleText"] = "我像这样找了好久\n也完全找不到皮卡丘。\011肯定不在这里吧！",
  ["_ViridianForestCooltrainerFBattleText"] = "嗨，\n你手上有皮卡丘吗？",
  ["_ViridianForestCooltrainerFEndBattleText"] = "骗人的吧！？",
  ["_ViridianForestSouthGateLittleGirlText"] = "如果想要收集各种宝可梦，\n就要到各种地方多走走呢。\012常青森林的外面\n还能找到其他宝可梦呢。",
  ["_ViridianForestYoungster2BattleText"] = "嗨！\n你有宝可梦的吧？\011我们来对战！",
  ["_ViridianForestYoungster5AfterBattleText"] = "通过变硬来攻击，\n铁甲蛹是最棒的！",
  ["_ViridianForestYoungster5BattleText"] = "我的目标是成为\n最强的训练家。\011你能打败我吗？",
  ["_ViridianForestYoungster5EndBattleText"] = "……我好不容易\n从绿毛虫培育起来的。",
  ["_ViridianForestYoungster6Text"] = "为了捉到宝可梦，\n身上的精灵球\011很快就用完了。\012我觉得你也应该多买一点，\n以备不时之需！",
  ["_ViridianGymCooltrainerM3AfterBattleText"] = "如果能打败……\n我们常青的馆主，\011你应该就能进入\011宝可梦联盟了吧。",
  ["_ViridianGymGiovanniPostBattleAdviceText"] = "以这样的方式输给你，\n我确实没有办法\011向部下交代！\011火箭队……\011就从今天起正式解散！\012我自己，\n则决定从头开始\011宝可梦的修行！\012希望有一天……\n我们还能有机会见面！\011……再见了！",
  ["_ViridianMartCooltrainerMText"] = "总是卖断货的伤药，\n现在终于能买到了！",
  ["_ViridianMartYoungsterText"] = "他们说，解麻药是\n这家店的畅销货呢！",
  ["_ViridianSchoolHouseLittleGirlText"] = "姐姐说过，\n如果好好对待宝可梦，\011它们就会和你变得亲近呢。",
  ["_VoltorbDexEntry"] = "据说它与精灵球相似的外形\n其实是保护色，但它很容易\n自爆这一点也出人意料。",
  ["_VulpixDexEntry"] = "皮毛和尾巴都非常美丽。\n随着自身成长，尾巴的末端\n渐渐分开，数量也会增加。",
  ["_WartortleDexEntry"] = "如果拍打它的头部，\n它会把头缩进壳里，但尾巴\n还是会露出来一点点。",
  ["_WeedleDexEntry"] = "头上长有尖锐的针。\n它喜欢藏在森林或草丛里\n大量吞食树叶。",
  ["_WeepinbellDexEntry"] = "它在肚子饿的时候会吞掉\n周围会动的东西，\n分泌溶解液让其致命。",
  ["_WeezingDexEntry"] = "它要靠吸收\n垃圾里的毒气、\n细菌和灰尘来维持生命。",
  ["_WigglytuffDexEntry"] = "身体非常有弹性，\n当它用力吸气时，\n身体可以无限制地膨胀。",
  ["_ZapdosDexEntry"] = "当天空黑暗，落雷不断时，\n这只传说的宝可梦\n就会出现。",
  ["_ZubatDexEntry"] = "由于需要调查前方的状况，\n它会一边从嘴里发出超音波\n一边飞行。",
}
